      "「浴びった」動詞應為「浴びた」，且「浴びる」意思是淋、沐浴，跟あらった不符，錯誤。",
      "「流れった」動詞變化不正確（「流れる」是自動詞，過去式應為「流れた」），且意思也不符，錯誤。"
